package com.example.featureapp.feature.reports

// Deliberately large, generated-looking report builder used to exercise the size bands.
class ReportsBuilder {
    fun section1(rows: List<String>): String {
        val out = StringBuilder()
        for (row in rows) {
            if (row.isNotEmpty()) {
                out.append("section1: ").append(row).append('\n')
            }
        }
        return out.toString()
    }

